import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";import"./chunks/assets.CGKUPeQw.js";var i=JSON.parse(`{"title":"AireFrame Release Notes","description":"","frontmatter":{},"headers":[],"relativePath":"aireblock-releases/AireFrame/aireframe-v3-3-0.md","filePath":"aireblock-releases/AireFrame/aireframe-v3-3-0.md","lastUpdated":1789394171000}`),a={name:`aireblock-releases/AireFrame/aireframe-v3-3-0.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="aireframe-release-notes" tabindex="-1"><span class="fsc-product"><img src="/aireframe-icon.png"> AireFrame Release Notes</span> <a class="header-anchor" href="#aireframe-release-notes" aria-label="Permalink to “AireFrame Release Notes”">​</a></h1><blockquote><p><strong>Version:</strong> v3.3.0<br><strong>Release Date:</strong> 23 September 2026</p></blockquote><h4 id="✨-new-features" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features" aria-label="Permalink to “✨ New Features”">​</a></h4><ul><li>Ad-Hoc Form Submission in the Subject Portal (FRAME-2571)</li><li>Configurable Form Types for the Portal (FRAME-2606)</li><li>Create Forms Directly from the Portal (FRAME-2607)</li><li>Secured Portal Form Creation (FRAME-2608)</li><li>Expanded Owner Type Options (FRAME-2664)</li><li>Git-Based Portal Form Configuration (FRAME-2666)</li><li>Customisable Default Sort for Subject Lists (FRAME-2683)</li><li>Server-Side Filtering for Allowed Portal Forms (FRAME-2684)</li><li>Complete Form List in Portal Configuration (FRAME-2685)</li><li>Correlation ID Support for Building Block Data Sets (FRAME-2692)</li></ul><h4 id="⚡-improvements" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements" aria-label="Permalink to “⚡ Improvements”">​</a></h4><ul><li>Smarter Liquid Expression Type Checking (FRAME-1862)</li><li>Improved Dashboard Configuration Page (FRAME-2471)</li><li>Quick Links to Data Pipelines and Data Sets (FRAME-2661)</li><li>Tenant Name in Portal Header (FRAME-2695)</li></ul><h4 id="🐞-bug-fixes" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h4><ul><li>Improved Visibility of Subject Assignments in Nested Structures (FRAME-2530)</li><li>Fixed Swapped Fields in Location Providers Config Export/Import (FRAME-2688)</li><li>Fixed Page Styling for Long Custom Field Names (FRAME-2698)</li></ul><h4 id="🔧-tasks" tabindex="-1">🔧 Tasks <a class="header-anchor" href="#🔧-tasks" aria-label="Permalink to “🔧 Tasks”">​</a></h4><ul><li>Reduced False &quot;Resource Locked&quot; Errors (FRAME-2713)</li></ul><h3 id="⚠️-upgrade-notes" tabindex="-1">⚠️ Upgrade Notes <a class="header-anchor" href="#⚠️-upgrade-notes" aria-label="Permalink to “⚠️ Upgrade Notes”">​</a></h3><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>The Owner Type field on the v2 GraphQL schema has changed from a fixed enum to a plain string, aligning AireFrame with the equivalent change in AireFlow. If your integration relies on the previous enum values for Owner Type, review and update it before upgrading.</p></div><h1 id="detailed-changes" tabindex="-1">Detailed Changes <a class="header-anchor" href="#detailed-changes" aria-label="Permalink to “Detailed Changes”">​</a></h1><h3 id="✨-new-features-1" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-1" aria-label="Permalink to “✨ New Features”">​</a></h3><hr><h4 id="ad-hoc-form-submission-in-the-subject-portal-frame-2571" tabindex="-1">Ad-Hoc Form Submission in the Subject Portal (FRAME-2571) <a class="header-anchor" href="#ad-hoc-form-submission-in-the-subject-portal-frame-2571" aria-label="Permalink to “Ad-Hoc Form Submission in the Subject Portal (FRAME-2571)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Portal users can now initiate and submit forms ad-hoc, without needing a form task first, using the same &quot;+&quot; button pattern already available in the clinician view. Availability can be gated by permission and tenant.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>If you use the portal, you can start and complete an available form yourself whenever you need to, rather than waiting for someone to send you a form task first.</p></div><h4 id="configurable-form-types-for-the-portal-frame-2606" tabindex="-1">Configurable Form Types for the Portal (FRAME-2606) <a class="header-anchor" href="#configurable-form-types-for-the-portal-frame-2606" aria-label="Permalink to “Configurable Form Types for the Portal (FRAME-2606)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Tenant configurators can now select one or more form keys to control which forms are available for ad-hoc creation in the portal, using the same configuration style as user group association.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>As a configurator, you can decide exactly which forms your portal users are allowed to create themselves, rather than exposing every form.</p></div><h4 id="create-forms-directly-from-the-portal-frame-2607" tabindex="-1">Create Forms Directly from the Portal (FRAME-2607) <a class="header-anchor" href="#create-forms-directly-from-the-portal-frame-2607" aria-label="Permalink to “Create Forms Directly from the Portal (FRAME-2607)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Portal users with the required permission can now create a form directly from the portal, choosing from the forms a tenant configurator has made available, with a searchable list so they don&#39;t need to already know the form&#39;s name.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>When you have permission, you can search for and start any of the forms your organisation has made available to you, right from the portal.</p></div><h4 id="secured-portal-form-creation-frame-2608" tabindex="-1">Secured Portal Form Creation (FRAME-2608) <a class="header-anchor" href="#secured-portal-form-creation-frame-2608" aria-label="Permalink to “Secured Portal Form Creation (FRAME-2608)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Authorisation checks in the AireFrame Forms Plugin have been updated so portal users can only create forms for themselves, not on behalf of anyone else, and only using form keys configured as allowed for the portal.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>When creating a form from the portal, you&#39;ll only ever be creating it for yourself, and only from the set of forms made available to you.</p></div><h4 id="expanded-owner-type-options-frame-2664" tabindex="-1">Expanded Owner Type Options (FRAME-2664) <a class="header-anchor" href="#expanded-owner-type-options-frame-2664" aria-label="Permalink to “Expanded Owner Type Options (FRAME-2664)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Owner Type has moved from a fixed enum to a plain string, aligning AireFrame with the equivalent change in AireFlow. Assignee Type already worked this way, with unrecognised values shown as &quot;unknown&quot; alongside their ID.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>Owner values are handled the same flexible way Assignee values already are, so unrecognised owners are shown clearly instead of being hidden.</p></div><h4 id="git-based-portal-form-configuration-frame-2666" tabindex="-1">Git-Based Portal Form Configuration (FRAME-2666) <a class="header-anchor" href="#git-based-portal-form-configuration-frame-2666" aria-label="Permalink to “Git-Based Portal Form Configuration (FRAME-2666)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Allowed portal form configuration can now also be managed via Git-based configuration, alongside the existing options.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>Portal form availability can be configured and version-controlled the same way as your other Git-managed configuration.</p></div><h4 id="customisable-default-sort-for-subject-lists-frame-2683" tabindex="-1">Customisable Default Sort for Subject Lists (FRAME-2683) <a class="header-anchor" href="#customisable-default-sort-for-subject-lists-frame-2683" aria-label="Permalink to “Customisable Default Sort for Subject Lists (FRAME-2683)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Tenants can now set the default sort order for the subject list, rather than it always defaulting to most recently created.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>You can choose the order subjects appear in by default, rather than always seeing the most recently created first.</p></div><h4 id="server-side-filtering-for-allowed-portal-forms-frame-2684" tabindex="-1">Server-Side Filtering for Allowed Portal Forms (FRAME-2684) <a class="header-anchor" href="#server-side-filtering-for-allowed-portal-forms-frame-2684" aria-label="Permalink to “Server-Side Filtering for Allowed Portal Forms (FRAME-2684)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Fetching a portal&#39;s available forms now asks the AireForms API for only the forms allowed by that portal&#39;s configuration, rather than fetching every form and filtering the result afterwards.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>Loading the list of forms available to you in the portal should be quicker and more consistent.</p></div><h4 id="complete-form-list-in-portal-configuration-frame-2685" tabindex="-1">Complete Form List in Portal Configuration (FRAME-2685) <a class="header-anchor" href="#complete-form-list-in-portal-configuration-frame-2685" aria-label="Permalink to “Complete Form List in Portal Configuration (FRAME-2685)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>The subject allowed-forms configuration screen now uses the new AireForms API and shows all forms regardless of layout or delivery status, rather than only clinician forms with a creatable status.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>When configuring which forms are allowed in the portal, you&#39;ll see the full list of forms to choose from, not just a subset.</p></div><h4 id="correlation-id-support-for-building-block-data-sets-frame-2692" tabindex="-1">Correlation ID Support for Building Block Data Sets (FRAME-2692) <a class="header-anchor" href="#correlation-id-support-for-building-block-data-sets-frame-2692" aria-label="Permalink to “Correlation ID Support for Building Block Data Sets (FRAME-2692)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Building block data sets linked to another data set can now access and group by correlation ID, which was previously unavailable because the building block had no knowledge of it.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>Grouping by correlation ID now works correctly when a building block data set is linked to another data set.</p></div><h3 id="⚡-improvements-1" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-1" aria-label="Permalink to “⚡ Improvements”">​</a></h3><hr><h4 id="smarter-liquid-expression-type-checking-frame-1862" tabindex="-1">Smarter Liquid Expression Type Checking (FRAME-1862) <a class="header-anchor" href="#smarter-liquid-expression-type-checking-frame-1862" aria-label="Permalink to “Smarter Liquid Expression Type Checking (FRAME-1862)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>AireFrame now infers the likely data type(s) of an identifier used in a liquid expression by tracking the operations applied to it, including backtracking through the identifiers it was derived from, to better determine whether an expression is valid for its input variables.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>Liquid expressions are checked more accurately against the data they&#39;re actually working with, helping catch invalid expressions earlier.</p></div><h4 id="improved-dashboard-configuration-page-frame-2471" tabindex="-1">Improved Dashboard Configuration Page (FRAME-2471) <a class="header-anchor" href="#improved-dashboard-configuration-page-frame-2471" aria-label="Permalink to “Improved Dashboard Configuration Page (FRAME-2471)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>The dashboard configuration page has been brought in line with the widgets, pipelines and data sets pages: dashboards are shown in a searchable table, and clicking a row opens a dedicated configuration page for that dashboard.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>Finding and configuring a dashboard is easier: you can search the list and click straight into the one you want, the same way you already can for widgets, pipelines and data sets.</p></div><h4 id="quick-links-to-data-pipelines-and-data-sets-frame-2661" tabindex="-1">Quick Links to Data Pipelines and Data Sets (FRAME-2661) <a class="header-anchor" href="#quick-links-to-data-pipelines-and-data-sets-frame-2661" aria-label="Permalink to “Quick Links to Data Pipelines and Data Sets (FRAME-2661)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Configuration pages now include a link icon that opens the related data pipeline or data set directly in a new tab, rather than requiring separate navigation through the configuration screens.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>You can jump straight to a linked data pipeline or data set from a configuration page, without hunting through menus.</p></div><h4 id="tenant-name-in-portal-header-frame-2695" tabindex="-1">Tenant Name in Portal Header (FRAME-2695) <a class="header-anchor" href="#tenant-name-in-portal-header-frame-2695" aria-label="Permalink to “Tenant Name in Portal Header (FRAME-2695)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>The AireFrame Portal header now shows the tenant name, matching the existing behaviour in AireFrame.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>You&#39;ll see which tenant you&#39;re working in directly in the portal header, just as you already can in AireFrame.</p></div><h3 id="🐞-bug-fixes-1" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-1" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><hr><h4 id="improved-visibility-of-subject-assignments-in-nested-structures-frame-2530" tabindex="-1">Improved Visibility of Subject Assignments in Nested Structures (FRAME-2530) <a class="header-anchor" href="#improved-visibility-of-subject-assignments-in-nested-structures-frame-2530" aria-label="Permalink to “Improved Visibility of Subject Assignments in Nested Structures (FRAME-2530)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Where a subject was assigned deep within a nested structure, there was no way to see this in the UI, which could make it look as though the subject wasn&#39;t assigned at all. The nested structure now expands to show the location the subject is assigned to.</p></div><h4 id="fixed-swapped-fields-in-location-providers-config-export-import-frame-2688" tabindex="-1">Fixed Swapped Fields in Location Providers Config Export/Import (FRAME-2688) <a class="header-anchor" href="#fixed-swapped-fields-in-location-providers-config-export-import-frame-2688" aria-label="Permalink to “Fixed Swapped Fields in Location Providers Config Export/Import (FRAME-2688)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>When an Upsert API location providers configuration was exported and then re-imported, certain fields were incorrectly swapped. This has been fixed so exported configuration re-imports correctly.</p></div><h4 id="fixed-page-styling-for-long-custom-field-names-frame-2698" tabindex="-1">Fixed Page Styling for Long Custom Field Names (FRAME-2698) <a class="header-anchor" href="#fixed-page-styling-for-long-custom-field-names-frame-2698" aria-label="Permalink to “Fixed Page Styling for Long Custom Field Names (FRAME-2698)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Long custom field names could break the page&#39;s styling on the custom field configuration page. Long names are now handled gracefully without disrupting the layout.</p></div><h3 id="🔧-tasks-1" tabindex="-1">🔧 Tasks <a class="header-anchor" href="#🔧-tasks-1" aria-label="Permalink to “🔧 Tasks”">​</a></h3><hr><h4 id="reduced-false-resource-locked-errors-frame-2713" tabindex="-1">Reduced False &quot;Resource Locked&quot; Errors (FRAME-2713) <a class="header-anchor" href="#reduced-false-resource-locked-errors-frame-2713" aria-label="Permalink to “Reduced False &quot;Resource Locked&quot; Errors (FRAME-2713)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Subject record updates and datapoint/visualisation cache recompute work previously shared a single lock, so an in-progress cache recompute could cause an unrelated subject record update to time out and fail with a 409 Conflict (&quot;resource is currently locked&quot;), and vice versa. These are now split into two separate locks so the two kinds of operation no longer block each other unnecessarily.</p></div>`,71)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};